def get_quadrant(r, c, min_r, max_r, min_c, max_c):
    """Get quadrant based on position relative to main region"""
    if r < min_r:
        top = True
        bot = False
    elif r > max_r:
        top = False
        bot = True
    else:
        top = False  # Inside vertically
        bot = False

    if c < min_c:
        left = True
        right = False
    elif c > max_c:
        left = False
        right = True
    else:
        left = False  # Inside horizontally
        right = False

    parts = []
    if top: parts.append("top")
    if bot: parts.append("bottom")
    if left: parts.append("left")
    if right: parts.append("right")
    return tuple(parts) if parts else "inside"

